     "support",
     "scope",
     "durability",
     "clarity",
     "breadth",
     "agreement",
     "conflicts",
   ]) {
     const v = requirements
       .map((r) => r.confidence?.signals.find((s) => s.key === key)?.value)
       .filter((x): x is number => x !== undefined);
